      call one_e_grad_22(sh_np(ii), sh_np(jj), sh_e(:, ii), sh_c(:, ii), sh_e(:, jj), sh_c(:, jj), &
                            sh_r(:, ii), sh_r(:, jj), natm, at_z, at_r, wt, wblk, dblk, ga, gb, &
                            gp(1:3, 1:natm, lane))
