         gb(2) = gb(2) + cc*wblk(1)*((2.0_dp*al*sy(1,0))*sx(2,2)*sz(0,0)) &
                         - cc*dblk(1)*((2.0_dp*al*ty(1,0))*sx(2,2)*sz(0,0) + (2.0_dp*al*sy(1,0))*(tx(2,2)*sz(0,0) + sx(2,2)*tz(0,0)))
         ga(3) = ga(3) - cc*wblk(1)*((2.0_dp*al*sz(1,0))*sx(2,2)*sy(0,0)) &
                         + cc*dblk(1)*((2.0_dp*al*tz(1,0))*sx(2,2)*sy(0,0) + (2.0_dp*al*sz(1,0))*(tx(2,2)*sy(0,0) + sx(2,2)*ty(0,0)))
         gb(3) = gb(3) + cc*wblk(1)*((2.0_dp*al*sz(1,0))*sx(2,2)*sy(0,0)) &
