            vn(3,2) = pay*vn(1,2) - pcy*vn(1,3)
            vn(4,2) = paz*vn(1,2) - pcz*vn(1,3)
            vn(5,2) = pax*vn(2,2) - pcx*vn(2,3) &
               + 1.0_dp*oo2z*(vn(1,2) - vn(1,3))
            vn(6,2) = pax*vn(3,2) - pcx*vn(3,3)
